-- Batch: DS-2027-002

INSERT INTO chapters (id, subject_id, code, name, sort_order)
SELECT CAST(c.id AS UUID), s.id, c.code, c.name, c.sort_order
FROM (
    VALUES
    ('00000000-0000-0000-0000-000000022201', 'DS_ARRAY_MATRIX', '数组和特殊矩阵', 14),
    ('00000000-0000-0000-0000-000000022202', 'DS_STRING', '串', 15),
    ('00000000-0000-0000-0000-000000022203', 'DS_SEARCH', '查找', 16)
) AS c(id, code, name, sort_order)
JOIN subjects s ON s.code = 'DATA_STRUCTURE'
WHERE NOT EXISTS (SELECT 1 FROM chapters existing WHERE existing.code = c.code);

INSERT INTO knowledge_points (id, chapter_id, code, name, sort_order)
SELECT CAST(kp.id AS UUID), c.id, kp.code, kp.name, kp.sort_order
FROM (
    VALUES
    ('00000000-0000-0000-0000-000000022301', 'DS_ARRAY_MATRIX', 'DS_ARRAY_MATRIX_COMPRESS', '数组与特殊矩阵压缩存储', 1),
    ('00000000-0000-0000-0000-000000022302', 'DS_STRING', 'DS_STRING_KMP', '串与 KMP 模式匹配', 1),
    ('00000000-0000-0000-0000-000000022303', 'DS_TREE', 'DS_TREE_HUFFMAN_UNION_FIND', '哈夫曼树与并查集', 2),
    ('00000000-0000-0000-0000-000000022304', 'DS_GRAPH', 'DS_GRAPH_APPLICATION', '图的应用', 2),
    ('00000000-0000-0000-0000-000000022305', 'DS_SEARCH', 'DS_SEARCH_LINEAR_BINARY', '顺序查找与折半查找', 1),
    ('00000000-0000-0000-0000-000000022306', 'DS_SEARCH', 'DS_SEARCH_TREE_HASH', '树形查找与散列查找', 2),
    ('00000000-0000-0000-0000-000000022307', 'DS_SORT', 'DS_SORT_INTERNAL_EXTERNAL', '内部排序与外部排序', 2)
) AS kp(id, chapter_code, code, name, sort_order)
JOIN chapters c ON c.code = kp.chapter_code
WHERE NOT EXISTS (SELECT 1 FROM knowledge_points existing WHERE existing.code = kp.code);

INSERT INTO questions (
    id, subject_id, chapter_id, type, difficulty, stem, answer, explanation,
    source, source_year, score, status, review_status, review_note,
    stem_format, stem_image_url, reviewed_at, created_at, updated_at
)
SELECT
    CAST(q.id AS UUID),
    s.id,
    c.id,
    'SINGLE_CHOICE',
    q.difficulty,
    q.stem,
    q.answer,
    q.explanation,
    'MOCK',
    2027,
    2.00,
    'PUBLISHED',
    'APPROVED',
    '基于 /Users/permer/Documents/408资料/2027数据结构_高清带书签版.pdf 的第二批教材章节与单选题考点改写导入。',
    'PLAIN_TEXT',
    NULL,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
FROM (
    VALUES
    ('00000000-0000-0000-0000-000000022001', 'DS_STACK_QUEUE', 'BASIC', '循环队列采用少用一个存储单元区分队空和队满，若数组容量为 m，则队满条件通常是？', 'B', '少用一个单元时，队满条件为 rear 的下一个位置等于 front，即 (rear + 1) mod m = front。'),
    ('00000000-0000-0000-0000-000000022002', 'DS_STACK_QUEUE', 'MEDIUM', '共享栈通常把两个栈设置在同一数组的两端向中间增长，其主要目的是什么？', 'C', '共享栈让两个栈共用一段连续空间，当二者增长方向相向时，可减少单个栈空间预分配造成的浪费。'),
    ('00000000-0000-0000-0000-000000022003', 'DS_STACK_QUEUE', 'HARD', '中缀表达式转换为后缀表达式时，运算符栈的核心作用是？', 'D', '运算符栈用于暂存尚不能输出的运算符，并按优先级和结合性控制输出顺序。'),
    ('00000000-0000-0000-0000-000000022004', 'DS_ARRAY_MATRIX', 'BASIC', '二维数组按行优先存储时，同一行中相邻元素在内存中的地址关系通常是？', 'A', '按行优先存储会先连续存放同一行元素，因此同一行相邻元素物理地址连续。'),
    ('00000000-0000-0000-0000-000000022005', 'DS_ARRAY_MATRIX', 'MEDIUM', 'n 阶对称矩阵进行压缩存储时，只保存下三角和主对角线元素，需要保存多少个元素？', 'C', '对称矩阵只需保存一个三角区域和主对角线，共 n(n+1)/2 个元素。'),
    ('00000000-0000-0000-0000-000000022006', 'DS_ARRAY_MATRIX', 'MEDIUM', 'n 阶三对角矩阵的非零元素个数最多为多少？', 'B', '三对角矩阵主对角线有 n 个元素，上下两条副对角线各 n-1 个元素，共 3n-2 个。'),
    ('00000000-0000-0000-0000-000000022007', 'DS_ARRAY_MATRIX', 'HARD', '稀疏矩阵采用三元组顺序表存储时，每个非零元素通常记录哪些信息？', 'D', '三元组通常记录非零元素的行号、列号和值，以便在压缩存储后仍可恢复矩阵位置。'),
    ('00000000-0000-0000-0000-000000022008', 'DS_STRING', 'BASIC', '串是一种特殊的线性表，其数据元素通常是什么？', 'B', '串是由零个或多个字符组成的有限序列，元素通常是字符。'),
    ('00000000-0000-0000-0000-000000022009', 'DS_STRING', 'MEDIUM', '朴素模式匹配算法在最坏情况下的时间复杂度通常为？', 'C', '主串长度为 n、模式串长度为 m 时，朴素匹配最坏可能在多个起点反复比较，复杂度为 O(nm)。'),
    ('00000000-0000-0000-0000-000000022010', 'DS_STRING', 'MEDIUM', 'KMP 算法相比朴素匹配的关键改进是？', 'A', 'KMP 利用模式串自身前后缀信息，失配时移动模式串而不回退主串指针。'),
    ('00000000-0000-0000-0000-000000022011', 'DS_STRING', 'HARD', 'KMP 中 next 数组主要反映模式串的哪类信息？', 'D', 'next 数组描述模式串前缀和后缀的匹配长度，用于决定失配后的回退位置。'),
    ('00000000-0000-0000-0000-000000022012', 'DS_TREE', 'MEDIUM', '含 n 个结点的二叉链表中，空链域个数为多少？', 'C', '二叉链表共有 2n 个链域，非空链域等于边数 n-1，因此空链域为 2n-(n-1)=n+1。'),
    ('00000000-0000-0000-0000-000000022013', 'DS_TREE', 'HARD', '仅已知一棵二叉树的先序序列和后序序列，通常能否唯一确定该二叉树？', 'B', '一般情况下先序和后序不能唯一确定二叉树，因为无法唯一划分左右子树。'),
    ('00000000-0000-0000-0000-000000022014', 'DS_TREE', 'MEDIUM', '哈夫曼树中，权值较大的叶结点通常具有怎样的路径长度？', 'A', '哈夫曼树为了最小化带权路径长度，通常让权值大的叶结点离根更近，路径长度更短。'),
    ('00000000-0000-0000-0000-000000022015', 'DS_GRAPH', 'BASIC', '无向图中所有顶点度数之和与边数 e 的关系是？', 'B', '无向图每条边贡献两个度，因此所有顶点度数之和为 2e。'),
    ('00000000-0000-0000-0000-000000022016', 'DS_GRAPH', 'MEDIUM', '广度优先搜索 BFS 通常需要借助哪种辅助结构？', 'C', 'BFS 按层扩展顶点，先发现的顶点先处理，通常使用队列。'),
    ('00000000-0000-0000-0000-000000022017', 'DS_GRAPH', 'MEDIUM', '拓扑排序适用于下列哪类图？', 'A', '拓扑排序用于有向无环图，表示顶点之间的先后约束关系。'),
    ('00000000-0000-0000-0000-000000022018', 'DS_SEARCH', 'BASIC', '折半查找要求待查找表通常满足什么条件？', 'A', '折半查找依赖关键字有序并可按下标随机访问，因此通常用于有序顺序表。'),
    ('00000000-0000-0000-0000-000000022019', 'DS_SEARCH', 'MEDIUM', '长度为 n 的有序顺序表进行折半查找，其平均查找长度数量级通常为？', 'B', '折半查找每次将查找区间减半，平均和最坏查找长度均为 O(log n) 数量级。'),
    ('00000000-0000-0000-0000-000000022020', 'DS_SEARCH', 'MEDIUM', '二叉排序树进行中序遍历时，得到的关键字序列通常是？', 'C', '二叉排序树左子树小于根、右子树大于根，中序遍历会得到递增有序序列。'),
    ('00000000-0000-0000-0000-000000022021', 'DS_SEARCH', 'HARD', 'm 阶 B 树中，除根结点外的非叶结点关键字个数通常至少为？', 'C', 'm 阶 B 树非根结点至少有 ceil(m/2) 个孩子，因此关键字个数至少为 ceil(m/2)-1。'),
    ('00000000-0000-0000-0000-000000022022', 'DS_SEARCH', 'MEDIUM', '散列表采用拉链法处理冲突时，同义词通常保存在哪里？', 'D', '拉链法将散列到同一地址的记录组织在同一个链表中。'),
    ('00000000-0000-0000-0000-000000022023', 'DS_SORT', 'BASIC', '稳定排序算法的含义是？', 'A', '稳定性指相等关键字记录在排序前后的相对次序保持不变。'),
    ('00000000-0000-0000-0000-000000022024', 'DS_SORT', 'MEDIUM', '快速排序一趟划分后，枢轴元素处于什么位置？', 'C', '一趟划分会把枢轴放到最终位置，左侧关键字不大于它，右侧关键字不小于它。')
) AS q(id, chapter_code, difficulty, stem, answer, explanation)
JOIN subjects s ON s.code = 'DATA_STRUCTURE'
JOIN chapters c ON c.code = q.chapter_code;

INSERT INTO question_options (id, question_id, label, content, sort_order)
SELECT CAST(CONCAT('00000000-0000-0000-0000-000000022', LPAD(CAST((q.num * 4 - 3) AS VARCHAR), 3, '0')) AS UUID), CAST(q.id AS UUID), 'A', q.option_a, 1
FROM (
    VALUES
    (1, '00000000-0000-0000-0000-000000022001', 'front = rear', '(rear + 1) mod m = front', 'rear = m', 'front = 0'),
    (2, '00000000-0000-0000-0000-000000022002', '保证两个栈元素有序', '让入栈复杂度变为 O(log n)', '提高存储空间利用率', '取消栈顶指针'),
