    (4, '00000000-0000-0000-0000-000000022004', '物理地址连续', '相隔一个完整列数', '必须通过指针连接', '一定不相邻'),
    (5, '00000000-0000-0000-0000-000000022005', 'n', 'n^2', 'n(n+1)/2', '2n - 1'),
    (6, '00000000-0000-0000-0000-000000022006', '2n - 1', '3n - 2', 'n(n+1)/2', 'n^2'),
    (7, '00000000-0000-0000-0000-000000022007', '行号、行数、列数', '值、前驱、后继', '上界、下界、步长', '行号、列号、元素值'),
    (8, '00000000-0000-0000-0000-000000022008', '任意整数', '字符', '指针结点', '图的顶点'),
    (9, '00000000-0000-0000-0000-000000022009', 'O(1)', 'O(n + m)', 'O(nm)', 'O(log n)'),
