    (11, '00000000-0000-0000-0000-000000022011', '每个字符的 ASCII 值', '主串中字符出现次数', '模式串长度的平方', '前缀与后缀的匹配关系'),
    (12, '00000000-0000-0000-0000-000000022012', 'n - 1', 'n', 'n + 1', '2n'),
    (13, '00000000-0000-0000-0000-000000022013', '一定可以', '通常不可以', '只有满二叉树不可以', '只要结点不同就一定可以'),
    (14, '00000000-0000-0000-0000-000000022014', '较短', '较长', '一定为 0', '与权值无关'),
    (15, '00000000-0000-0000-0000-000000022015', 'e', '2e', 'e - 1', 'e + 1'),
    (16, '00000000-0000-0000-0000-000000022016', '栈', '堆', '队列', '散列表'),
    (17, '00000000-0000-0000-0000-000000022017', '有向无环图', '任意无向图', '完全无向图', '带负权回路的图'),
    (18, '00000000-0000-0000-0000-000000022018', '有序且支持随机访问', '必须链式存储', '关键字必须互不相同且无序', '只能是散列表'),
    (19, '00000000-0000-0000-0000-000000022019', 'O(1)', 'O(log n)', 'O(n)', 'O(n^2)'),
    (20, '00000000-0000-0000-0000-000000022020', '先序序列', '层次序列', '递增有序序列', '完全随机序列'),
    (21, '00000000-0000-0000-0000-000000022021', '1', 'm - 1', 'ceil(m/2) - 1', 'm'),
    (22, '00000000-0000-0000-0000-000000022022', '连续的下一个空单元', '栈顶', '另一个数组的主对角线', '同一地址对应的链表中'),
