    (1, '00000000-0000-0000-0000-000000022001', 'front = rear', '(rear + 1) mod m = front', 'rear = m', 'front = 0'), (2, '00000000-0000-0000-0000-000000022002', '保证两个栈元素有序', '让入栈复杂度变为 O(log n)', '提高存储空间利用率', '取消栈顶指针'), (3, '00000000-0000-0000-0000-000000022003', '保存所有操作数的最终值', '按字典序排序变量名', '删除所有括号', '暂存运算符并处理优先级'), (4, '00000000-0000-0000-0000-000000022004', '物理地址连续', '相隔一个完整列数', '必须通过指针连接', '一定不相邻'), (5, '00000000-0000-0000-0000-000000022005', 'n', 'n^2', 'n(n+1)/2', '2n - 1'), (6, '00000000-0000-0000-0000-000000022006', '2n - 1', '3n - 2', 'n(n+1)/2', 'n^2'), (7, '00000000-0000-0000-0000-000000022007', '行号、行数、列数', '值、前驱、后继', '上界、下界、步长', '行号、列号、元素值'), (8, '00000000-0000-0000-0000-000000022008', '任意整数', '字符', '指针结点', '图的顶点'), (9, '00000000-0000-0000-0000-000000022009', 'O(1)', 'O(n + m)', 'O(nm)', 'O(log n)'), (10, '00000000-0000-0000-0000-000000022010', '主串指针不回退', '每次都从头比较模式串', '删除模式串中的重复字符', '把串改为链式存储'), (11, '00000000-0000-0000-0000-000000022011', '每个字符的 ASCII 值', '主串中字符出现次数', '模式串长度的平方', '前缀与后缀的匹配关系'), (12, '00000000-0000-0000-0000-000000022012', 'n - 1', 'n', 'n + 1', '2n'), (13, '00000000-0000-0000-0000-000000022013', '一定可以', '通常不可以', '只有满二叉树不可以', '只要结点不同就一定可以'), (14, '00000000-0000-0000-0000-000000022014', '较短', '较长', '一定为 0', '与权值无关'), (15, '00000000-0000-0000-0000-000000022015', 'e', '2e', 'e - 1', 'e + 1'), (16, '00000000-0000-0000-0000-000000022016', '栈', '堆', '队列', '散列表'), (17, '00000000-0000-0000-0000-000000022017', '有向无环图', '任意无向图', '完全无向图', '带负权回路的图'), (18, '00000000-0000-0000-0000-000000022018', '有序且支持随机访问', '必须链式存储', '关键字必须互不相同且无序', '只能是散列表'), (19, '00000000-0000-0000-0000-000000022019', 'O(1)', 'O(log n)', 'O(n)', 'O(n^2)'), (20, '00000000-0000-0000-0000-000000022020', '先序序列', '层次序列', '递增有序序列', '完全随机序列'), (21, '00000000-0000-0000-0000-000000022021', '1', 'm - 1', 'ceil(m/2) - 1', 'm'), (22, '00000000-0000-0000-0000-000000022022', '连续的下一个空单元', '栈顶', '另一个数组的主对角线', '同一地址对应的链表中'), (23, '00000000-0000-0000-0000-000000022023', '相等关键字相对次序不变', '时间复杂度恒为 O(