INSERT INTO question_tags (id, name, created_at)
SELECT CAST(tag.id AS UUID), tag.name, CURRENT_TIMESTAMP
FROM (
    VALUES
    ('00000000-0000-0000-0000-000000022701', 'DS-2027-002')
) AS tag(id, name)
WHERE NOT EXISTS (SELECT 1 FROM question_tags existing WHERE existing.name = tag.name);

INSERT INTO question_tag_relations (question_id, tag_id)
SELECT CAST(q.id AS UUID), tag.id
FROM (
    VALUES
    ('00000000-0000-0000-0000-000000022001'), ('00000000-0000-0000-0000-000000022002'), ('00000000-0000-0000-0000-000000022003'), ('00000000-0000-0000-0000-000000022004'),
    ('00000000-0000-0000-0000-000000022005'), ('00000000-0000-0000-0000-000000022006'), ('00000000-0000-0000-0000-000000022007'), ('00000000-0000-0000-0000-000000022008'),
    ('00000000-0000-0000-0000-000000022009'), ('00000000-0000-0000-0000-000000022010'), ('00000000-0000-0000-0000-000000022011'), ('00000000-0000-0000-0000-000000022012'),
    ('00000000-0000-0000-0000-000000022013'), ('00000000-0000-0000-0000-000000022014'), ('00000000-0000-0000-0000-000000022015'), ('00000000-0000-0000-0000-000000022016'),
    ('00000000-0000-0000-0000-000000022017'), ('00000000-0000-0000-0000-000000022018'), ('00000000-0000-0000-0000-000000022019'), ('00000000-0000-0000-0000-000000022020'),
    ('00000000-0000-0000-0000-000000022021'), ('00000000-0000-0000-0000-000000022022'), ('00000000-0000-0000-0000-000000022023'), ('00000000-0000-0000-0000-000000022024')
) AS q(id)
JOIN question_tags tag ON tag.name IN ('2027数据结构', 'DS-2027-002', '资料文档改写', '选择题扩容')
WHERE NOT EXISTS (
    SELECT 1 FROM question_tag_relations existing
    WHERE existing.question_id = CAST(q.id AS UUID)
      AND existing.tag_id = tag.id
);
